import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Eigene Blocks und Template-Pakete","description":"","frontmatter":{"title":"Eigene Blocks und Template-Pakete"},"headers":[],"relativePath":"projects/blocks-for-ha/custom-blocks.md","filePath":"projects/blocks-for-ha/custom-blocks.md","lastUpdated":1792851046000}'),o={name:"projects/blocks-for-ha/custom-blocks.md"};function a(s,e,l,d,u,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="eigene-blocks-und-template-pakete" tabindex="-1">Eigene Blocks und Template-Pakete <a class="header-anchor" href="#eigene-blocks-und-template-pakete" aria-label="Permalink to &quot;Eigene Blocks und Template-Pakete&quot;">​</a></h1><p>Seit <strong>0.1.18</strong> öffnet <strong>Block-/Template-Editor</strong> neben dem Automationsnamen einen Dialog mit 95 % Fensterbreite und -höhe. Auf Mobilgeräten nutzt er 98 % und scrollt intern. Felder gestalten den Block; rechts stehen eine echte Blockly-Vorschau, die HA-Ausgabe mit Beispielwerten und kopierbares Paket-JSON.</p><h2 id="erstellen-und-ubernehmen" tabindex="-1">Erstellen und übernehmen <a class="header-anchor" href="#erstellen-und-ubernehmen" aria-label="Permalink to &quot;Erstellen und übernehmen&quot;">​</a></h2><ol><li>Paket-ID, Version, Name, Autor, Lizenz und Beschreibung eintragen oder <strong>Beispiel laden</strong> wählen.</li><li>Einen oder mehrere Blocks hinzufügen: <strong>Wert/Jinja</strong>, <strong>Bedingung/Jinja</strong>, <strong>Aktion/HA-YAML</strong> oder <strong>Auslöser/HA-YAML</strong>.</li><li>Felder für Text, Zahl, Boolean oder Entität und Werteingänge für Number, String, Boolean oder Value anlegen.</li><li>Jinja-Ausdruck beziehungsweise deklarative HA-Zuordnung eintragen und Vorschau prüfen.</li><li><strong>Übernehmen</strong> installiert das Paket lokal. Seine Blocks stehen unter <strong>Benutzerdefiniert</strong> unmittelbar vor der Suche.</li></ol><p>Jinja-Ausdrücke werden ohne äußere Template-Klammern angegeben. Platzhalter wie <code>${ENTITY}</code> verweisen auf Feld- oder Eingangsnamen. Felder werden typgerecht eingesetzt; Werteingänge werden als Ausdrücke geklammert. Die HA-Zuordnung verwendet ganze JSON-Werte wie <code>{&quot;$field&quot;:&quot;ENTITY&quot;}</code> oder <code>{&quot;$input&quot;:&quot;VALUE&quot;}</code>. Das <a href="./catalog/sensor-light">Beispiel Sensor und Licht</a> zeigt alle Zuordnungen.</p><h2 id="zwei-importwege-und-veroffentlichung" tabindex="-1">Zwei Importwege und Veröffentlichung <a class="header-anchor" href="#zwei-importwege-und-veroffentlichung" aria-label="Permalink to &quot;Zwei Importwege und Veröffentlichung&quot;">​</a></h2><ul><li><strong>Code einfügen:</strong> Paket-JSON unter „JSON-Code oder ZIP importieren“ einfügen, <strong>JSON prüfen</strong>, Vorschau ansehen, <strong>Übernehmen</strong>.</li><li><strong>ZIP einlesen:</strong> Paketdatei auswählen, Vorschau ansehen, <strong>Übernehmen</strong>.</li></ul><p><strong>JSON herunterladen</strong>, <strong>Code kopieren</strong> und <strong>Katalog-ZIP herunterladen</strong> exportieren dasselbe Paket. Das ZIP enthält <code>block-package.json</code> und <code>README.md</code>. Die Open-Source-Seiten erklären die Pakete und bieten Code und Downloads; der separate <a href="https://visualstudio.ugso-software.de/blocks" target="_blank" rel="noreferrer">Katalog</a> erhält eine eigene Blockpaket-Seite. Neue Veröffentlichungen werden manuell geprüft; der Editor lädt nichts automatisch hoch. <a href="./catalog/">Katalog und Beispiel</a>.</p><h2 id="speicherung-und-konflikte" tabindex="-1">Speicherung und Konflikte <a class="header-anchor" href="#speicherung-und-konflikte" aria-label="Permalink to &quot;Speicherung und Konflikte&quot;">​</a></h2><p>Paketformat <code>ugso-ha-block-package</code>, <code>schemaVersion: 1</code>; Paket-/Block-IDs bestehen aus Kleinbuchstaben, Ziffern und einzelnen Unterstrichen. Installierte Pakete bleiben in diesem Browser gespeichert. Projektformat <strong>3</strong> bettet verwendete Pakete samt Abhängigkeiten ein. Projektformate 1 und 2 bleiben lesbar. Ein fehlerhafter Projektimport installiert keine neuen Paketdefinitionen.</p><p>Identische Pakete können erneut importiert werden. Eine bestehende Paket-ID mit anderem Inhalt oder anderer Version wird zurückgewiesen. Für eine eigene Variante eine neue Paket-ID verwenden; automatische Updates und Deinstallation folgen später. Abhängigkeiten müssen mit passender exakter Version vorhanden sein oder gemeinsam im Projekt eingebettet werden. Zyklische Abhängigkeiten werden abgelehnt.</p><p>Grenzen: 16 installierte Pakete, 32 Blocks je Paket, 12 Felder und 8 Werteingänge je Block; JSON höchstens 500.000 Zeichen, ZIP höchstens 1 MB komprimiert und entpackt. ZIPs erlauben ausschließlich die beiden beschriebenen Dateien.</p><h2 id="grenzen-des-ersten-editors" tabindex="-1">Grenzen des ersten Editors <a class="header-anchor" href="#grenzen-des-ersten-editors" aria-label="Permalink to &quot;Grenzen des ersten Editors&quot;">​</a></h2><p>Der Editor ist eine eigene HA-orientierte Oberfläche mit Blockly-Vorschau. Der originale <a href="https://docs.blockly.com/guides/create-custom-blocks/blockly-developer-tools/" target="_blank" rel="noreferrer">Blockly Block Factory</a> ist noch nicht eingebettet. Dessen rohes Block-JSON allein enthält keine HA-Funktion und ist kein importierbares UGSo-Paket. JavaScript-/Python-/PHP-/Lua-/Dart-Generatoren werden nicht importiert oder ausgeführt.</p><p>Dropdowns, Variablenfelder, Bilder, Statement-Container, Mutatoren und dynamische Anschlüsse im eigenen Editor bleiben auf der Roadmap. Werteingänge sind typgeprüft; vorhandene Blocks mit ausschließlich festen Zahlenfeldern nehmen weiterhin keine dynamischen Zahlenwerte an.</p><p>Die Vorschau prüft Paket- und unterstützte HA-Strukturen, führt Jinja aber nicht aus. Geräteeigenschaften und gültige Parameterbereiche müssen in HA geprüft werden; numerische Felder bieten derzeit keine frei definierbaren Min-/Max-Grenzen. Der Editor führt keine HA-Aktionen aus. Ein YAML-Export enthält native HA-Strukturen; beim YAML-Reimport entsteht die entsprechende native Darstellung. Die ursprünglichen benutzerdefinierten Blockformen bleiben über die JSON-Projektdatei erhalten.</p>',16)])])}const k=n(o,[["render",a]]);export{g as __pageData,k as default};
